const CUSTOM = "https://example.org/captionCode";
const candidates = [
  { value: "RDFS name", language: "en", property: RDFS_LABEL },
  { value: "Custom caption", language: "en", property: CUSTOM },
];

test("an explicit predicate order selects same-language labels before default vocabulary fallbacks", () => {
  assert.equal(chooseLabel(candidates, ["en"], [CUSTOM, RDFS_LABEL]), "Custom caption");
  assert.equal(chooseLabel(candidates, ["en"], [RDFS_LABEL, CUSTOM]), "RDFS name");
  assert.equal(chooseLabel([...candidates, { value: "Norsk navn", language: "nb", property: RDFS_LABEL }],
    ["nb", "en"], [CUSTOM, RDFS_LABEL]), "Norsk navn");
});

test("ordered predicate policies remain isolated in persisted metadata and apply to predicates and types", async () => {
  clearMetadataCache();
  const ids = ["https://example.org/person", "https://example.org/worksFor", "https://example.org/Person"];
  let calls = 0;
  const query = async () => {
    calls++;
    return { results: { bindings: ids.flatMap(resource => candidates.map(candidate => ({
      resource: { type: "uri", value: resource },
      labelProperty: { type: "uri", value: candidate.property },
      label: { type: "literal", value: `${candidate.value} ${resource.split("/").at(-1)}`, "xml:lang": "en" },
    }))) } };
  };
  const graph = { revision: 1, nodes: [
    { id: ids[0], kind: "iri", label: "person", types: [{ id: ids[2], label: "Person" }] },
  ], edges: [{ id: "e", source: ids[0], target: ids[0], predicate: ids[1], label: "works for" }] };
  const make = properties => new RdfExplorer("urn:ordered-policy", ["en"], query, "default", false, false,
    "repository", properties);
  const custom = make([CUSTOM, RDFS_LABEL]);
  try {
    await custom.resolve(ids);
    const displayed = custom.apply(graph);
    assert.equal(displayed.nodes[0].label, "Custom caption person");
    assert.equal(displayed.nodes[0].types[0].label, "Custom caption Person");
    assert.equal(displayed.edges[0].label, "Custom caption worksFor");
  } finally { custom.dispose(); }
  const rdfs = make([RDFS_LABEL, CUSTOM]);
  try {
    await rdfs.resolve(ids);
    assert.equal(rdfs.label(ids[0]), "RDFS name person");
    assert.equal(calls, 2, "changing predicate order must not reuse another policy's checked cache");
  } finally { rdfs.dispose(); }
});

test("language order respects regional variants, wildcard position and untagged labels", () => {
  const multilingual = [
    { value: "English", language: "en-US", property: RDFS_LABEL },
    { value: "Norsk", language: "nb-NO", property: RDFS_LABEL },
    { value: "Untagged", language: "", property: RDFS_LABEL },
    { value: "Deutsch", language: "de", property: LABEL_PROPERTIES[0] },
  ];
  assert.equal(chooseLabel(multilingual, ["nb", "en"]), "Norsk");
  assert.equal(chooseLabel(multilingual, ["en-GB", "nb"]), "English");
  assert.equal(chooseLabel(multilingual, ["und", "nb"]), "Untagged");
  assert.equal(chooseLabel(multilingual, ["*", "nb"]), "Deutsch");
  assert.equal(chooseLabel(multilingual, ["nb", "*"]), "Norsk");
  assert.equal(chooseLabel([
    { value: "Exact Norwegian", language: "nb", property: CUSTOM },
    { value: "Regional Norwegian", language: "nb-NO", property: RDFS_LABEL },
  ], ["nb"], [RDFS_LABEL, CUSTOM]), "Exact Norwegian", "exact language matches precede regional fallbacks");
});

test("a rendered fallback or previous chosen name is not promoted to an untagged supplied label", async () => {
  clearMetadataCache();
  const id = "https://example.org/Book";
  const graph = { revision: 1, nodes: [{ id, kind: "iri", label: "Book" }], edges: [] };
  const first = new RdfExplorer("urn:provenance", ["en"], async () => ({ results: { bindings: [{
    resource: { type: "uri", value: id }, labelProperty: { type: "uri", value: RDFS_LABEL },
    label: { type: "literal", value: "English title", "xml:lang": "en" },
  }] } }));
  await first.resolve([id]);
  const displayed = first.apply(graph);
  first.dispose();
  const next = new RdfExplorer("urn:provenance", ["und"], async () => ({ results: { bindings: [{
    resource: { type: "uri", value: id }, labelProperty: { type: "uri", value: RDFS_LABEL },
    label: { type: "literal", value: "Deutscher Titel", "xml:lang": "de" },
  }] } }));
  try {
    next.observe(displayed);
    await next.resolve([id]);
    assert.equal(next.apply(displayed).nodes[0].label, "Deutscher Titel");
  } finally { next.dispose(); }
});

test("language and predicate priorities compose for every available pair", () => {
  for (const languages of [["nb", "en"], ["en", "nb"]]) {
    for (const properties of [[CUSTOM, RDFS_LABEL], [RDFS_LABEL, CUSTOM]]) {
      const all = languages.flatMap(language => properties.map(property => ({
        language, property, value: `${language} ${property === CUSTOM ? "custom" : "RDFS"}`,
      })));
      for (const absent of [null, all[0], all[1], all[2], all[3]]) {
        const available = all.filter(candidate => candidate !== absent);
        assert.equal(chooseLabel(available.slice().reverse(), languages, properties), available[0].value);
      }
    }
  }
});

