test("guidance retains vocabulary and language diversity before candidate trimming and across checked cache hits", async () => {
  clearMetadataCache();
  const id = "urn:label-diversity";
  let calls = 0;
  const query = async () => {
    calls++;
    return { results: { bindings: Array.from({ length: 140 }, (_, index) => ({
      resource: { type: "uri", value: id }, labelProperty: { type: "uri", value: RDFS_LABEL },
      label: { type: "literal", value: `English name ${index}`, "xml:lang": "en" },
    })).concat([{
      resource: { type: "uri", value: id }, labelProperty: { type: "uri", value: LABEL_PROPERTIES[0] },
      label: { type: "literal", value: "Nom français", "xml:lang": "fr" },
    }]) } };
  };
  const first = new RdfExplorer("urn:label-diversity-cache", ["en"], query);
  await first.resolve([id]);
  const evidence = first.labelEvidence([id]);
  assert.deepEqual(new Set(evidence.properties), new Set([RDFS_LABEL, LABEL_PROPERTIES[0]]));
  assert.deepEqual(new Set(evidence.languages), new Set(["en", "fr"]));
  assert.equal(evidence.complete, true);
  first.dispose();
  const cached = new RdfExplorer("urn:label-diversity-cache", ["en"], query);
  try {
    await cached.resolve([id]);
    assert.deepEqual(cached.labelEvidence([id]), evidence);
    assert.equal(calls, 1);
  } finally { cached.dispose(); }
});

