const policyModule = () => import("../../../main/frontend/graph-explorer/label-policy.ts");
const memoryStorage = () => {
  const values = new Map();
  return { getItem: key => values.get(key) ?? null, setItem: (key, value) => values.set(key, value),
    removeItem: key => values.delete(key) };
};

test("locale defaults, legacy migration, independent configured dimensions and corrupted storage are safe", async () => {
  const { defaultLabelPolicy, readLabelPolicy, saveLabelPolicy, parseLabelPolicy, LABEL_POLICY_STORAGE_KEY } = await policyModule();
  const storage = memoryStorage();
  const defaults = defaultLabelPolicy(["nb-NO", "en-US", "nb-no"]);
  assert.deepEqual(defaults.languages, ["nb-no", "en-us"]);
  assert.equal(defaults.languagesConfigured, false);
  assert.equal(defaults.propertiesConfigured, false);
  assert.ok(defaults.properties.includes(RDFS_LABEL));
  assert.deepEqual(defaultLabelPolicy([]).languages, ["en"]);
  storage.setItem("graph-field-language-preferences-v1", JSON.stringify(["de", "und"]));
  const migrated = readLabelPolicy(storage, ["nb"]);
  assert.deepEqual(migrated.languages, ["de", "und"]);
  assert.equal(migrated.languagesConfigured, true);
  assert.equal(migrated.propertiesConfigured, false);
  const custom = { ...migrated, properties: [CUSTOM, RDFS_LABEL], propertiesConfigured: true };
  saveLabelPolicy(storage, custom);
  assert.deepEqual(readLabelPolicy(storage, ["fr"]), custom);
  assert.equal(storage.getItem("graph-field-language-preferences-v1"), null);
  assert.equal(parseLabelPolicy('{broken', ["fr"]), null);
  assert.equal(parseLabelPolicy(JSON.stringify({ ...custom, languages: ["en\"}"] }), ["fr"]), null);
  storage.setItem(LABEL_POLICY_STORAGE_KEY, "{broken");
  assert.deepEqual(readLabelPolicy(storage, ["fr"]).languages, ["fr"]);
  const blocked = { getItem() { throw new Error("blocked"); }, setItem() { throw new Error("blocked"); }, removeItem() {} };
  assert.deepEqual(readLabelPolicy(blocked, ["de"]).languages, ["de"]);
  assert.doesNotThrow(() => saveLabelPolicy(blocked, custom));
});

test("guidance uses positive label evidence, successful completion, and independent configured dimensions", async () => {
  const { defaultLabelPolicy, labelGuidance } = await policyModule();
  const policy = defaultLabelPolicy(["en"]);
  const seen = { properties: [RDFS_LABEL, LABEL_PROPERTIES[0]], languages: ["en", "nb"], complete: true };
  const ids = value => value.map(reason => reason.id).sort();
  assert.deepEqual(ids(labelGuidance(policy, seen)), ["multiple-languages", "multiple-properties"]);
  assert.deepEqual(labelGuidance(policy, { properties: [], languages: [], complete: true }), []);
  assert.deepEqual(labelGuidance(policy, { properties: ["urn:graph-field:supplied"], languages: ["en"], complete: true }), []);
  const configured = { ...policy, languages: ["de"], languagesConfigured: true, properties: [CUSTOM], propertiesConfigured: true };
  assert.deepEqual(ids(labelGuidance(configured, seen)), ["unmatched-languages", "unmatched-properties"]);
  assert.deepEqual(labelGuidance(configured, { ...seen, complete: false }), [], "failed or pending discovery cannot prove mismatch");
  assert.deepEqual(ids(labelGuidance({ ...configured, languagesConfigured: false }, seen)),
    ["multiple-languages", "unmatched-properties"]);
  assert.deepEqual(ids(labelGuidance({ ...configured, propertiesConfigured: false }, seen)),
    ["multiple-properties", "unmatched-languages"]);
  for (const languages of [["en-GB"], ["nb"], ["*"]]) {
    assert.ok(!ids(labelGuidance({ ...configured, languages }, { ...seen, languages: ["nb-NO", "en-US"] }))
      .includes("unmatched-languages"));
  }
  assert.ok(!ids(labelGuidance({ ...configured, languages: ["und"] }, { ...seen, languages: [""] }))
    .includes("unmatched-languages"));
});

test("dismissal categories persist independently for each repository and server", async () => {
  const { defaultLabelPolicy, labelGuidance, readDismissedLabelGuidance, saveDismissedLabelGuidance } = await policyModule();
  const { repositoryScope } = await import("../../../main/frontend/graph-explorer/repository-identity.ts");
  const storage = memoryStorage();
  const repo = repositoryScope("/workbench", "one", "server-a");
  const otherRepo = repositoryScope("/workbench", "two", "server-a");
  const otherServer = repositoryScope("/workbench", "one", "server-b");
  const policy = defaultLabelPolicy(["en"]);
  const evidence = { properties: [RDFS_LABEL, LABEL_PROPERTIES[0]], languages: ["en", "nb"], complete: true };
  const reasons = labelGuidance(policy, evidence);
  saveDismissedLabelGuidance(storage, repo, reasons.map(reason => reason.id));
  const dismissed = readDismissedLabelGuidance(storage, repo);
  assert.deepEqual(labelGuidance(policy, evidence, dismissed), []);
  assert.deepEqual(labelGuidance(policy, { ...evidence, languages: ["de", "fr"] }, dismissed), []);
  assert.equal(readDismissedLabelGuidance(storage, otherRepo).length, 0);
  assert.equal(readDismissedLabelGuidance(storage, otherServer).length, 0);
  const configured = { ...policy, languages: ["de"], languagesConfigured: true };
  assert.deepEqual(labelGuidance(configured, evidence, dismissed).map(reason => reason.id), ["unmatched-languages"]);
});

test("known predicate captions identify vocabulary aliases without collapsing schema schemes or custom IRIs", async () => {
  const { labelPropertyCaption, defaultLabelPolicy } = await policyModule();
  const captions = defaultLabelPolicy(["en"]).properties.map(labelPropertyCaption);
  assert.equal(new Set(captions).size, captions.length);
  assert.equal(labelPropertyCaption("https://schema.org/name"), "schema:name (HTTPS)");
  assert.equal(labelPropertyCaption("http://schema.org/name"), "schema:name (HTTP)");
  assert.equal(labelPropertyCaption("http://xmlns.com/foaf/0.1/name"), "foaf:name");
  assert.equal(labelPropertyCaption("http://purl.org/dc/terms/title"), "dcterms:title");
  assert.equal(labelPropertyCaption("http://purl.org/dc/elements/1.1/title"), "dc:title");
  assert.equal(labelPropertyCaption(CUSTOM), CUSTOM);
});
